/* Doctor website – static interactive demo (vanilla JS, hash routing, in-memory state only) */
const $=(s,r=document)=>r.querySelector(s);
const bn=n=>Number(n).toLocaleString('bn-BD');
const tk=n=>'৳'+bn(n);
const fd=s=>new Date(s+'T00:00:00').toLocaleDateString('bn-BD',{day:'numeric',month:'long',year:'numeric'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=s=>`<span class="badge bg-${ST[s][1]}">${ST[s][0]}</span>`;
const cc=c=>CC[c]||['#0a6ebd','#12a36b'];
const ph=(icon,c,h=150,cls='')=>`<div class="ph ${cls}" style="height:${h}px;background:linear-gradient(135deg,${c[0]},${c[1]})"><i class="bi ${icon}"></i></div>`;
const S={cart:[],user:false,pay:'cod',bk:{step:1,svc:null,date:null,time:null,info:{}},f:{q:'',cat:'সব',sort:'',max:5000},pf:'all',month:new Date(),last:null};
let ROUTE='home',AFTER=null,M=null;
const SLOTS=['সকাল ১০:০০','সকাল ১০:৩০','সকাল ১১:০০','সকাল ১১:৩০','বিকেল ৫:০০','বিকেল ৫:৩০','সন্ধ্যা ৬:০০','সন্ধ্যা ৬:৩০','সন্ধ্যা ৭:০০','রাত ৮:০০'];
const PAY=[['cod','ক্যাশ অন ডেলিভারি','bi-cash-coin',1],['bkash','বিকাশ (শীঘ্রই আসছে)','bi-phone',0],['nagad','নগদ (শীঘ্রই আসছে)','bi-wallet2',0],['ssl','SSLCommerz (শীঘ্রই আসছে)','bi-credit-card-2-front',0],['demo','ডেমো পেমেন্ট','bi-lightning-charge',1]];
const cartN=()=>S.cart.reduce((a,c)=>a+c.qty,0);
const prod=id=>PRODUCTS.find(p=>p.id==id);
const sub=()=>S.cart.reduce((a,c)=>a+prod(c.id).price*c.qty,0);
const ship=()=>(!S.cart.length||sub()>=2000)?0:60;
const rid=p=>p+'-'+(1000+Math.floor(Math.random()*9000));
const myAppts=()=>APPTS.filter(a=>a.patient===ME.name),myOrders=()=>ORDERS.filter(o=>o.cust===ME.name),myDons=()=>DONATIONS.filter(d=>d.donor===ME.name);
const otot=o=>o.items.reduce((a,i)=>a+i.p*i.q,0);

/* ---------- UI helpers ---------- */
function toast(m,t='success'){const e=document.createElement('div');e.className=`toast show align-items-center text-bg-${t} border-0 mb-2`;e.innerHTML=`<div class="d-flex"><div class="toast-body">${m}</div><button class="btn-close btn-close-white me-2 m-auto" onclick="this.closest('.toast').remove()"></button></div>`;$('#toasts').appendChild(e);setTimeout(()=>e.remove(),3800)}
function modal(title,body,btns){const el=$('#mdl');$('.modal-title',el).textContent=title;$('.modal-body',el).innerHTML=body;const f=$('.modal-footer',el);f.innerHTML='';(btns||[{t:'বন্ধ করুন',c:'btn-light'}]).forEach(b=>{const x=document.createElement('button');x.className='btn '+(b.c||'btn-brand');x.textContent=b.t;x.onclick=()=>{if(!b.keep)M.hide();if(b.f)b.f(el)};f.appendChild(x)});M=M||new bootstrap.Modal(el);M.show()}
const ask=(msg,fn)=>modal('নিশ্চিত করুন',`<p class="mb-0">${msg}</p>`,[{t:'না',c:'btn-light'},{t:'হ্যাঁ',f:fn}]);
function formModal(title,fields,save){const b=`<form id="fm" novalidate>${fields.map(f=>`<div class="mb-3"><label class="form-label">${f.l}</label>${f.t==='select'?`<select class="form-select" name="${f.k}">${f.o.map(o=>`<option ${o==f.v?'selected':''}>${o}</option>`).join('')}</select>`:f.t==='textarea'?`<textarea class="form-control" name="${f.k}" rows="3">${esc(f.v||'')}</textarea>`:`<input class="form-control" name="${f.k}" type="${f.t||'text'}" value="${esc(f.v??'')}" required>`}</div>`).join('')}</form>`;
 modal(title,b,[{t:'বাতিল',c:'btn-light'},{t:'সংরক্ষণ (ডেমো)',keep:true,f:el=>{const fm=$('#fm',el);if(!fm.checkValidity()){fm.classList.add('was-validated');return}M.hide();save(Object.fromEntries(new FormData(fm)))}}])}
const crumbs=a=>`<nav class="container pt-3"><ol class="breadcrumb small mb-0"><li class="breadcrumb-item"><a href="#/home">হোম</a></li>${a.map((x,i)=>i<a.length-1?`<li class="breadcrumb-item"><a href="${x[1]}">${x[0]}</a></li>`:`<li class="breadcrumb-item active">${x[0]}</li>`).join('')}</ol></nav>`;
const head=(t,sub,a)=>`${a?crumbs(a):''}<div class="container py-3"><h2 class="fw-bold mb-1">${t}</h2>${sub?`<p class="text-muted mb-0">${sub}</p>`:''}</div>`;
const tbl=(heads,rows)=>`<div class="card card-soft"><div class="table-responsive"><table class="table table-hover rtable mb-0"><thead class="table-light"><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((c,i)=>`<td data-label="${heads[i]||''}" class="${heads[i]===''||heads[i]==='অ্যাকশন'?'act':''}">${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="text-center text-muted py-4">কিছু নেই</td></tr>`}</tbody></table></div></div>`;
const bnav=items=>`<nav class="bottom-nav d-lg-none">${items.map(([r,i,l])=>`<a href="#/${r}" class="${ROUTE===r||ROUTE.startsWith(r+'/')?'on':''}"><i class="bi ${i}"></i>${l}</a>`).join('')}</nav>`;
const nl=(r,l)=>`<li class="nav-item"><a class="nav-link ${ROUTE===r?'active fw-semibold':''}" href="#/${r}">${l}</a></li>`;
const dash=()=>S.user?'p/dashboard':'login';

